def read(p):
    return json.loads(Path(p).read_text())

def sha(p):
    h = hashlib.sha256()
    with Path(p).open('rb') as f:
        for b in iter(lambda : f.read(1048576), b''):
            h.update(b)
    return h.hexdigest()

def save(p, d):
    Path(p).write_text(json.dumps(d, indent=2, allow_nan=False) + '\n')

